mapper.select:
SELECT refresh_token 
FROM user 
WHERE user_id = #{userId}

mapper.update:
UPDATE user 
SET refresh_token = #{refreshToken} 
WHERE user_id = #{userId}

mapper.select:
SELECT user_id
FROM user
WHERE user_name = #{name} AND user_email = #{email}

mapper.update:
UPDATE user 
SET user_password = #{newPw} 
WHERE user_id = #{userId}

mapper.select:
SELECT EXISTS (
    SELECT 1 
    FROM user 
    WHERE user_id = #{userId}
)
